     1→const std = @import("std");
     2→const Air = @import("air.zig").Air;
     3→const AirType = @import("air.zig").Type;
     4→const Ref = @import("air.zig").Ref;
     5→const Instruction = @import("air.zig").Instruction;
     6→const PatternType = @import("air.zig").PatternType;
     7→
     8→/// Phase 4.3: Defer 엔트리
     9→pub const DeferEntry = struct {
    10→    expr_ref: Ref,
    11→    defer_index: u32,
    12→};
    13→
    14→/// C 코드 생성기 (AIR → C 코드)
    15→pub const Codegen = struct {
    16→    air: *const Air,
    17→    allocator: std.mem.Allocator,
    18→    output: std.ArrayList(u8),
    19→    indent_level: usize,
    20→    temp_counter: u32,
    21→    ref_to_temp: std.AutoHashMap(Ref, []const u8),
    22→    switch_subject_stack: std.ArrayList([]const u8),  // Phase 4.1: 중첩 switch 지원
    23→    error_counter: u32,                               // Phase 4.2: 에러 변수 카운터
    24→    try_ref_to_err: std.AutoHashMap(Ref, []const u8), // Phase 4.2: try ref → "_err_N"
    25→    deferred_by_scope: std.AutoHashMap(u32, std.ArrayList(DeferEntry)), // Phase 4.3: scope별 defer
    26→
    27→    pub fn init(allocator: std.mem.Allocator, air: *const Air) !Codegen {
    28→        return Codegen{
    29→            .air = air,
    30→            .allocator = allocator,
    31→            .output = std.ArrayList(u8).init(allocator),
    32→            .indent_level = 0,
    33→            .temp_counter = 0,
    34→            .ref_to_temp = std.AutoHashMap(Ref, []const u8).init(allocator),
    35→            .switch_subject_stack = std.ArrayList([]const u8).init(allocator),
    36→            .error_counter = 0,
    37→            .try_ref_to_err = std.AutoHashMap(Ref, []const u8).init(allocator),
    38→            .deferred_by_scope = std.AutoHashMap(u32, std.ArrayList(DeferEntry)).init(allocator),
    39→        };
    40→    }
    41→
    42→    pub fn deinit(self: *Codegen) void {
    43→        self.output.deinit();
    44→        self.ref_to_temp.deinit();
    45→        self.switch_subject_stack.deinit();
    46→        self.try_ref_to_err.deinit();
    47→
    48→        var iter = self.deferred_by_scope.iterator();
    49→        while (iter.next()) |entry| {
    50→            entry.value_ptr.deinit();
    51→        }
    52→        self.deferred_by_scope.deinit();
    53→    }
    54→
    55→    /// AIR 프로그램을 C 코드로 생성
    56→    pub fn generate(self: *Codegen) ![]const u8 {
    57→        try self.emitHeaders();
    58→        try self.emitDeclarations();
    59→        return self.output.items;
    60→    }
    61→
    62→    /// 생성된 C 코드를 파일로 저장
    63→    pub fn generateToFile(self: *Codegen, path: []const u8) !void {
    64→        const c_code = try self.generate();
    65→        const file = try std.fs.cwd().createFile(path, .{});
    66→        defer file.close();
    67→        try file.writeAll(c_code);
    68→    }
    69→
    70→    // ========== 헤더 & 기본 구조 ==========
    71→
    72→    fn emitHeaders(self: *Codegen) !void {
    73→        try self.output.appendSlice("#include <stdio.h>\n");
    74→        try self.output.appendSlice("#include <string.h>\n");
    75→        try self.output.appendSlice("#include <stdlib.h>\n\n");
    76→    }
    77→
    78→    fn emitDeclarations(self: *Codegen) !void {
    79→        for (self.air.instructions.items, 0..) |inst, idx| {
    80→            const ref: Ref = @intCast(idx);
    81→            try self.emitInstruction(inst, ref);
    82→        }
    83→    }
    84→
    85→    // ========== 타입 변환 ==========
    86→
    87→    fn typeToCString(self: *Codegen, ty: AirType) ![]const u8 {
    88→        _ = self;
    89→        return switch (ty) {
    90→            .void => "void",
    91→            .i32 => "int",
    92→            .i64 => "long long",
    93→            .f32 => "float",
    94→            .f64 => "double",
    95→            .bool => "int",
    96→            .string => "const char*",
    97→            .array => "array", // TODO: 배열 타입 처리
    98→            .function => "function", // TODO: 함수 포인터
    99→            .error_type => "int",         // Phase 4: 에러 코드
   100→            .error_union => "int",        // Phase 4: 에러 유니온
   101→            .pattern => "int",            // Phase 4: 패턴 매치 결과
   102→            .slice => "void*",            // Phase 4: 슬라이스는 포인터
   103→            .unknown => "int", // 기본값
   104→        };
   105→    }
   106→
   107→    /// Ref를 C 코드 표현으로 변환 (변수명 또는 리터럴)
   108→    fn refToString(self: *Codegen, ref: Ref) ![]const u8 {
   109→        if (self.ref_to_temp.get(ref)) |temp| {
   110→            return temp;
   111→        }
   112→        return try std.fmt.allocPrint(self.allocator, "_t{}", .{ref});
   113→    }
   114→
   115→    /// 새로운 임시 변수 생성
   116→    fn genTempVar(self: *Codegen) ![]const u8 {
   117→        const name = try std.fmt.allocPrint(self.allocator, "_t{}", .{self.temp_counter});
   118→        self.temp_counter += 1;
   119→        return name;
   120→    }
   121→
   122→    // ========== Instruction 코드 생성 ==========
   123→
   124→    fn emitInstruction(self: *Codegen, inst: Instruction, ref: Ref) !void {
   125→        switch (inst) {
   126→            .load_int => |info| {
   127→                try self.emitLoadInt(info, ref);
   128→            },
   129→            .load_float => |info| {
   130→                try self.emitLoadFloat(info, ref);
   131→            },
   132→            .load_string => |info| {
   133→                try self.emitLoadString(info, ref);
   134→            },
   135→            .load_var => |info| {
   136→                try self.emitLoadVar(info, ref);
   137→            },
   138→            .store_var => |info| {
   139→                try self.emitStoreVar(info);
   140→            },
   141→            .binary_op => |info| {
   142→                try self.emitBinaryOp(info, ref);
   143→            },
   144→            .unary_op => |info| {
   145→                try self.emitUnaryOp(info, ref);
   146→            },
   147→            .fn_begin => |info| {
   148→                try self.emitFnBegin(info);
   149→            },
   150→            .fn_end => {
   151→                try self.emitFnEnd();
   152→            },
   153→            .call => |info| {
   154→                try self.emitCall(info, ref);
   155→            },
   156→            .cond_br => |info| {
   157→                try self.emitCondBr(info);
   158→            },
   159→            .return_val => |info| {
   160→                try self.emitReturnVal(info);
   161→            },
   162→            .block_begin => {
   163→                try self.emitIndent();
   164→                try self.output.appendSlice("{\n");
   165→                self.indent_level += 1;
   166→            },
   167→            .block_end => {
   168→                if (self.indent_level > 0) self.indent_level -= 1;
   169→                try self.emitIndent();
   170→                try self.output.appendSlice("}\n");
   171→            },
   172→            .array_literal => |info| {
   173→                try self.emitArrayLiteral(info, ref);
   174→            },
   175→            .index_access => |info| {
   176→                try self.emitIndexAccess(info, ref);
   177→            },
   178→            .member_access => |info| {
   179→                try self.emitMemberAccess(info, ref);
   180→            },
   181→            .loop_begin => {
   182→                try self.emitIndent();
   183→                try self.output.appendSlice("while (1) {\n");
   184→                self.indent_level += 1;
   185→            },
   186→            .loop_end => {
   187→                if (self.indent_level > 0) self.indent_level -= 1;
   188→                try self.emitIndent();
   189→                try self.output.appendSlice("}\n");
   190→            },
   191→            .switch_expr => |info| {
   192→                try self.emitSwitchExpr(info, ref);
   193→            },
   194→            .case_pattern => |info| {
   195→                try self.emitCasePattern(info, ref);
   196→            },
   197→            .try_expr => |info| {
   198→                try self.emitTryExpr(info, ref);
   199→            },
   200→            .catch_expr => |info| {
   201→                try self.emitCatchExpr(info, ref);
   202→            },
   203→            .defer_stmt => |info| {
   204→                try self.emitDeferStmt(info, ref);
   205→            },
   206→            .scope_exit => |info| {
   207→                try self.emitScopeExit(info);
   208→            },
   209→            .noop => {},
   210→            else => {},
   211→        }
   212→    }
   213→
   214→    fn emitLoadInt(self: *Codegen, info: struct { value: i64, ty: AirType }, ref: Ref) !void {
   215→        try self.emitIndent();
   216→        const type_str = try self.typeToCString(info.ty);
   217→        try self.output.appendSlice(type_str);
   218→        try self.output.appendSlice(" _t");
   219→        try self.output.writer().print("{} = {};\n", .{ ref, info.value });
   220→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   221→    }
   222→
   223→    fn emitLoadFloat(self: *Codegen, info: struct { value: f64, ty: AirType }, ref: Ref) !void {
   224→        try self.emitIndent();
   225→        const type_str = try self.typeToCString(info.ty);
   226→        try self.output.appendSlice(type_str);
   227→        try self.output.appendSlice(" _t");
   228→        try self.output.writer().print("{} = {};\n", .{ ref, info.value });
   229→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   230→    }
   231→
   232→    fn emitLoadString(self: *Codegen, info: struct { index: u32, ty: AirType }, ref: Ref) !void {
   233→        try self.emitIndent();
   234→        const type_str = try self.typeToCString(info.ty);
   235→        const str_value = if (info.index < self.air.strings.items.len)
   236→            self.air.strings.items[info.index]
   237→        else
   238→            "\"\"";
   239→        try self.output.writer().print("{} _t{} = {};\n", .{ type_str, ref, str_value });
   240→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   241→    }
   242→
   243→    fn emitLoadVar(self: *Codegen, info: struct { name_index: u32, ty: AirType }, ref: Ref) !void {
   244→        try self.emitIndent();
   245→        const type_str = try self.typeToCString(info.ty);
   246→        const var_name = if (info.name_index < self.air.strings.items.len)
   247→            self.air.strings.items[info.name_index]
   248→        else
   249→            "unknown";
   250→        try self.output.writer().print("{} _t{} = {};\n", .{ type_str, ref, var_name });
   251→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   252→    }
   253→
   254→    fn emitStoreVar(self: *Codegen, info: struct { name_index: u32, value: Ref, ty: AirType }) !void {
   255→        try self.emitIndent();
   256→        const var_name = if (info.name_index < self.air.strings.items.len)
   257→            self.air.strings.items[info.name_index]
   258→        else
   259→            "unknown";
   260→        const val_str = try self.refToString(info.value);
   261→        try self.output.writer().print("{} = {};\n", .{ var_name, val_str });
   262→    }
   263→
   264→    fn emitBinaryOp(self: *Codegen, info: struct { op: u8, lhs: Ref, rhs: Ref, result_ty: AirType }, ref: Ref) !void {
   265→        try self.emitIndent();
   266→        const type_str = try self.typeToCString(info.result_ty);
   267→        const op_str = switch (info.op) {
   268→            0 => "+",    // add
   269→            1 => "-",    // sub
   270→            2 => "*",    // mul
   271→            3 => "/",    // div
   272→            4 => "%",    // mod
   273→            5 => "==",   // eq
   274→            6 => "!=",   // ne
   275→            7 => "<",    // lt
   276→            8 => "<=",   // le
   277→            9 => ">",    // gt
   278→            10 => ">=",  // ge
   279→            11 => "&&",  // and
   280→            12 => "||",  // or
   281→            13 => "^",   // xor
   282→            14 => "<<",  // lshift
   283→            15 => ">>",  // rshift
   284→            else => "+",
   285→        };
   286→        const lhs_str = try self.refToString(info.lhs);
   287→        const rhs_str = try self.refToString(info.rhs);
   288→        try self.output.writer().print("{} _t{} = {} {} {};\n", .{ type_str, ref, lhs_str, op_str, rhs_str });
   289→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   290→    }
   291→
   292→    fn emitUnaryOp(self: *Codegen, info: struct { op: u8, operand: Ref, result_ty: AirType }, ref: Ref) !void {
   293→        try self.emitIndent();
   294→        const type_str = try self.typeToCString(info.result_ty);
   295→        const op_str = switch (info.op) {
   296→            0 => "-",  // negate
   297→            1 => "!",  // not
   298→            2 => "~",  // bitwise_not
   299→            else => "-",
   300→        };
   301→        const operand_str = try self.refToString(info.operand);
   302→        try self.output.writer().print("{} _t{} = {}{};\n", .{ type_str, ref, op_str, operand_str });
   303→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   304→    }
   305→
   306→    fn emitFnBegin(self: *Codegen, info: struct { name_index: u32, params: []Ref, return_ty: AirType }) !void {
   307→        try self.emitIndent();
   308→        const fn_name = if (info.name_index < self.air.strings.items.len)
   309→            self.air.strings.items[info.name_index]
   310→        else
   311→            "unknown";
   312→        const return_str = try self.typeToCString(info.return_ty);
   313→        try self.output.writer().print("{} {}(", .{ return_str, fn_name });
   314→
   315→        // 파라미터 출력 (간단하게 int로 표현)
   316→        for (0..info.params.len) |i| {
   317→            if (i > 0) try self.output.appendSlice(", ");
   318→            try self.output.writer().print("int p{}", .{i});
   319→        }
   320→        try self.output.appendSlice(") {\n");
   321→        self.indent_level += 1;
   322→    }
   323→
   324→    fn emitFnEnd(self: *Codegen) !void {
   325→        if (self.indent_level > 0) self.indent_level -= 1;
   326→        try self.emitIndent();
   327→        try self.output.appendSlice("}\n\n");
   328→    }
   329→
   330→    fn emitCall(self: *Codegen, info: struct { callee: Ref, args: []Ref, return_ty: AirType }, ref: Ref) !void {
   331→        try self.emitIndent();
   332→        const type_str = try self.typeToCString(info.return_ty);
   333→        const callee_str = try self.refToString(info.callee);
   334→        try self.output.writer().print("{} _t{} = {}(", .{ type_str, ref, callee_str });
   335→
   336→        for (0..info.args.len) |i| {
   337→            if (i > 0) try self.output.appendSlice(", ");
   338→            const arg_str = try self.refToString(info.args[i]);
   339→            try self.output.appendSlice(arg_str);
   340→        }
   341→        try self.output.appendSlice(");\n");
   342→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   343→    }
   344→
   345→    fn emitCondBr(self: *Codegen, info: struct { cond: Ref, then_block: Ref, else_block: ?Ref }) !void {
   346→        try self.emitIndent();
   347→        const cond_str = try self.refToString(info.cond);
   348→        _ = info.else_block; // 단순 if 처리, else는 별도 블록
   349→        try self.output.writer().print("if ({}) ", .{cond_str});
   350→    }
   351→
   352→    fn emitReturnVal(self: *Codegen, value: ?Ref) !void {
   353→        try self.emitIndent();
   354→        try self.output.appendSlice("return");
   355→        if (value) |v| {
   356→            try self.output.appendSlice(" ");
   357→            const val_str = try self.refToString(v);
   358→            try self.output.appendSlice(val_str);
   359→        }
   360→        try self.output.appendSlice(";\n");
   361→    }
   362→
   363→    fn emitArrayLiteral(self: *Codegen, info: struct { elements: []Ref, element_ty: AirType }, ref: Ref) !void {
   364→        try self.emitIndent();
   365→        const type_str = try self.typeToCString(info.element_ty);
   366→        try self.output.writer().print("{} _t{}[] = {{ ", .{ type_str, ref });
   367→        for (0..info.elements.len) |i| {
   368→            if (i > 0) try self.output.appendSlice(", ");
   369→            const elem_str = try self.refToString(info.elements[i]);
   370→            try self.output.appendSlice(elem_str);
   371→        }
   372→        try self.output.appendSlice(" };\n");
   373→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   374→    }
   375→
   376→    fn emitIndexAccess(self: *Codegen, info: struct { array: Ref, index: Ref, element_ty: AirType }, ref: Ref) !void {
   377→        try self.emitIndent();
   378→        const type_str = try self.typeToCString(info.element_ty);
   379→        const array_str = try self.refToString(info.array);
   380→        const index_str = try self.refToString(info.index);
   381→        try self.output.writer().print("{} _t{} = {}[{}];\n", .{ type_str, ref, array_str, index_str });
   382→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   383→    }
   384→
   385→    fn emitMemberAccess(self: *Codegen, info: struct { object: Ref, field_index: u32, field_ty: AirType }, ref: Ref) !void {
   386→        try self.emitIndent();
   387→        const type_str = try self.typeToCString(info.field_ty);
   388→        const object_str = try self.refToString(info.object);
   389→        const field_name = if (info.field_index < self.air.strings.items.len)
   390→            self.air.strings.items[info.field_index]
   391→        else
   392→            "field";
   393→        try self.output.writer().print("{} _t{} = {}.{};\n", .{ type_str, ref, object_str, field_name });
   394→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   395→    }
   396→
   397→    // ========== Phase 4.1: Pattern Matching Codegen ==========
   398→
   399→    fn emitSwitchExpr(self: *Codegen, info: struct { expr: Ref, cases: []Ref, case_patterns: []AirType }, ref: Ref) !void {
   400→        // switch 주제 표현식 가져오기
   401→        const subject_str = try self.refToString(info.expr);
   402→
   403→        // 중첩 switch 지원을 위해 스택에 주제 push
   404→        try self.switch_subject_stack.append(subject_str);
   405→
   406→        // switch 결과값 저장소 매핑
   407→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   408→    }
   409→
   410→    fn emitCasePattern(self: *Codegen, info: struct { pattern: Ref, value: Ref, pattern_ty: AirType }, ref: Ref) !void {
   411→        // 현재 switch 주제 가져오기 (스택 peek)
   412→        if (self.switch_subject_stack.items.len == 0) {
   413→            return; // switch가 없으면 무시
   414→        }
   415→        const subject_str = self.switch_subject_stack.items[self.switch_subject_stack.items.len - 1];
   416→
   417→        // 패턴 타입에 따라 조건 생성
   418→        const is_first = false; // 더 정교한 구현에서는 case 인덱스 추적 필요
   419→
   420→        try self.emitIndent();
   421→
   422→        // wildcard 패턴 (`_`) 감지
   423→        if (std.mem.eql(u8, subject_str, "_")) {
   424→            try self.output.appendSlice("else ");
   425→        } else {
   426→            if (is_first) {
   427→                try self.output.appendSlice("if (");
   428→            } else {
   429→                try self.output.appendSlice("} else if (");
   430→            }
   431→            try self.output.appendSlice(subject_str);
   432→            try self.output.appendSlice(" == _t");
   433→            try self.output.writer().print("{}", .{info.pattern});
   434→            try self.output.appendSlice(") ");
   435→        }
   436→
   437→        try self.output.appendSlice("{\n");
   438→        self.indent_level += 1;
   439→
   440→        // case body 저장 (값으로 매핑)
   441→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{info.value}));
   442→    }
   443→
   444→    fn emitPatternBinding(self: *Codegen, name: []const u8, subject: []const u8, ty: AirType, ref: Ref) !void {
   445→        try self.emitIndent();
   446→        const type_str = try self.typeToCString(ty);
   447→        try self.output.writer().print("{} {} = {};\n", .{ type_str, name, subject });
   448→        try self.ref_to_temp.put(ref, try self.allocator.dupe(u8, name));
   449→    }
   450→
   451→    // ========== Phase 4.2: Error Handling Codegen ==========
   452→
   453→    fn emitTryExpr(self: *Codegen, info: struct { expr: Ref, result_type: AirType }, ref: Ref) !void {
   454→        // 새로운 에러 변수 생성: _err_N
   455→        const err_var = try std.fmt.allocPrint(self.allocator, "_err_{}", .{self.error_counter});
   456→        self.error_counter += 1;
   457→
   458→        // 에러 변수 선언
   459→        try self.emitIndent();
   460→        try self.output.writer().print("int {} = 0;\n", .{err_var});
   461→
   462→        // 내부 표현식 실행 (이미 emitted된 상태)
   463→        // try expr의 결과를 임시 변수에 저장
   464→        try self.emitIndent();
   465→        const result_type = try self.typeToCString(info.result_type);
   466→        try self.output.writer().print("{} _t{} = _t{};\n", .{ result_type, ref, info.expr });
   467→
   468→        // 에러 전파 guard check
   469→        try self.emitIndent();
   470→        try self.output.writer().print("if ({} != 0) return {};\n", .{ err_var, err_var });
   471→
   472→        // try_ref_to_err에 매핑 저장
   473→        try self.try_ref_to_err.put(ref, err_var);
   474→
   475→        // 결과값 매핑
   476→        try self.ref_to_temp.put(ref, try std.fmt.allocPrint(self.allocator, "_t{}", .{ref}));
   477→    }
   478→
   479→    fn emitCatchExpr(self: *Codegen, info: struct { try_expr: Ref, error_var_type: AirType, body: Ref }, _: Ref) !void {
   480→        // try_expr에서 생성한 에러 변수 조회
   481→        if (self.try_ref_to_err.get(info.try_expr)) |err_var| {
   482→            // catch 블록 시작
   483→            try self.emitIndent();
   484→            try self.output.writer().print("if ({} != 0) {{\n", .{err_var});
   485→            self.indent_level += 1;
   486→
   487→            // 에러 변수 바인딩 (catch |err|)
   488→            try self.emitIndent();
   489→            const err_type = try self.typeToCString(info.error_var_type);
   490→            try self.output.writer().print("{} err = {};\n", .{ err_type, err_var });
   491→
   492→            // body는 이미 emitted된 블록
   493→            // catch 블록은 body instruction이 처리하는 동안 유지
   494→
   495→            self.indent_level -= 1;
   496→            try self.emitIndent();
   497→            try self.output.appendSlice("}\n");
   498→        }
   499→    }
   500→
   501→    // ========== Phase 4.3: Defer & Scope Codegen ==========
   502→
   503→    fn emitDeferStmt(self: *Codegen, info: struct { expr: Ref, scope_id: u32, defer_index: u32 }, _: Ref) !void {
   504→        // defer 식을 scope별 큐에 저장 (현재는 emitting하지 않음)
   505→        var deferred = self.deferred_by_scope.get(info.scope_id);
   506→        if (deferred == null) {
   507→            var new_list = std.ArrayList(DeferEntry).init(self.allocator);
   508→            try self.deferred_by_scope.put(info.scope_id, new_list);
   509→            deferred = self.deferred_by_scope.get(info.scope_id);
   510→        }
   511→
   512→        try deferred.?.append(.{
   513→            .expr_ref = info.expr,
   514→            .defer_index = info.defer_index,
   515→        });
   516→    }
   517→
   518→    fn emitScopeExit(self: *Codegen, info: struct { scope_id: u32 }, _: Ref) !void {
   519→        // 해당 scope의 defer들을 역순(defer_index 내림차순)으로 정렬 후 emit
   520→        if (self.deferred_by_scope.get(info.scope_id)) |defer_list| {
   521→            var defers = defer_list.items;
   522→            // 내림차순 정렬 (높은 defer_index가 먼저 실행)
   523→            std.mem.sort(DeferEntry, defers, {}, deferIndexDescending);
   524→
   525→            for (defers) |defer_entry| {
   526→                try self.emitIndent();
   527→                const expr_str = try self.refToString(defer_entry.expr_ref);
   528→                try self.output.writer().print("{};\n", .{expr_str});
   529→            }
   530→        }
   531→    }
   532→
   533→    /// defer_index 내림차순 정렬 함수
   534→    fn deferIndexDescending(_: void, a: DeferEntry, b: DeferEntry) bool {
   535→        return a.defer_index > b.defer_index;
   536→    }
   537→
   538→    // ========== 유틸리티 ==========
   539→
   540→    fn emitIndent(self: *Codegen) !void {
   541→        for (0..self.indent_level) |_| {
   542→            try self.output.appendSlice("    ");
   543→        }
   544→    }
   545→};
