   252→        stdout.print("{s}[{}] ", .{ spaces, idx }) catch {};
   253→
   254→        switch (inst) {
   255→            .load_int => |data| {
   256→                stdout.print("load_int {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   257→            },
   258→            .load_float => |data| {
   259→                stdout.print("load_float {} ({s})\n", .{ data.value, typeName(data.ty) }) catch {};
   260→            },
   261→            .load_string => |data| {
   262→                stdout.print("load_string @{} ({s})\n", .{ data.index, typeName(data.ty) }) catch {};
   263→            },
   264→            .load_var => |data| {
   265→                stdout.print("load_var @{} ({s})\n", .{ data.name_index, typeName(data.ty) }) catch {};
   266→            },
   267→            .store_var => |data| {
   268→                stdout.print("store_var @{} = %{} ({s})\n", .{ data.name_index, data.value, typeName(data.ty) }) catch {};
   269→            },
   270→            .binary_op => |data| {
   271→                stdout.print("binary_op {:s} %{} %{} → {s}\n", .{ @tagName(data.op), data.lhs, data.rhs, typeName(data.result_ty) }) catch {};
   272→            },
   273→            .unary_op => |data| {
   274→                stdout.print("unary_op {:s} %{} → {s}\n", .{ @tagName(data.op), data.operand, typeName(data.result_ty) }) catch {};
   275→            },
   276→            .fn_begin => |data| {
   277→                stdout.print("fn_begin @{} (params: {}, return: {s})\n", .{ data.name_index, data.params.len, typeName(data.return_ty) }) catch {};
   278→            },
   279→            .fn_end => {
   280→                stdout.print("fn_end\n", .{}) catch {};
   281→            },
   282→            .call => |data| {
   283→                stdout.print("call %{} (args: {}, return: {s})\n", .{ data.callee, data.args.len, typeName(data.return_ty) }) catch {};
