   289→                    stdout.print("return void\n", .{}) catch {};
   290→                }
   291→            },
   292→            .block_begin => |data| {
   293→                stdout.print("block_begin @{}\n", .{data.label}) catch {};
   294→            },
   295→            .block_end => {
   296→                stdout.print("block_end\n", .{}) catch {};
   297→            },
   298→            .array_literal => |data| {
   299→                stdout.print("array_literal (elements: {}, type: {s})\n", .{ data.elements.len, typeName(data.element_ty) }) catch {};
   300→            },
   301→            .noop => {
   302→                stdout.print("noop\n", .{}) catch {};
   303→            },
   304→            else => {
   305→                stdout.print("{s}\n", .{@tagName(inst)}) catch {};
   306→            },
   307→        }
   308→    }
   309→
   310→    stdout.print("{s}=== Strings ===\n", .{spaces}) catch {};
